/**
 * The declared-type tables of the four schema sets: the type each global element and each element
 * particle of a content model is declared with, and the names of the types a schema set holds.
 *
 * Data only. Each export is an array of plain rows, in the form of `wildcard.ts`; no relation
 * seeds from them. The importer reads them to judge an `xsi:type` against the type its element is
 * declared with. The derivation lives in `xsi.test.ts`, which reads the QTI schema documents from
 * the shared cache with the repository's own XML reader, follows each schema set's `xs:import`,
 * `xs:include` and `xs:redefine` from its root documents, and asserts every row below equal to what
 * the documents declare. No derivation lives anywhere else.
 *
 * A schema set is a validator's closure of documents. `asi` and `manifest` have one root document
 * per version (3.0.0 and 3.0.1); `lom` and `usagedata` have one, written for both versions.
 *
 * - `declaredRoot`: each global element declaration whose namespace a registry names on this base,
 *   with its declared type. The MathML and SSML rows are the joins of their phases.
 * - `declaredChild`: each element particle (a local declaration, or a reference to a global) of a
 *   complex type's content model, through `xs:group` references and `xs:sequence`, `xs:choice` and
 *   `xs:all`, with its declared type and its parent type. A type derived by extension holds its
 *   base's particles as well; a restriction holds its own, which it restates. A parent is a named
 *   complex type of a registry namespace, or an anonymous complex type held by a declaration.
 * - `namedTypes`: every named simple and complex type in the set's closure, every namespace included,
 *   so that a foreign element's `xsi:type` can be told resolved from unresolved, and XML Schema's
 *   own: `xs:anyType`, `xs:anySimpleType` and the 44 built-in datatypes of XML Schema Part 2,
 *   section 3.
 *
 * A type key is `{ namespace, local }` for a named type, or `{ anonymous }` for one with no name,
 * the path of the declaration that holds it: the global element, or the named type or group it is
 * written inside, then each enclosing local element, each name preceded by its namespace's code.
 * An element declared with neither `type` nor a type definition has `xs:anyType`.
 *
 * The rows are written as one string each, `<parent> <element> <type>` for a particle,
 * `<element> <type>` for a root and `<name>` for a type name, where a name is `<code>:<local>`
 * (the code is a key of `typeNamespaces`) and an anonymous type is `!<path>`.
 */
import type { SchemaSetHandle } from "#pantry/schema/content/rosters.ts";
import type { SchemaVersionHandle } from "#pantry/schema/kinds/generic.ts";
import { namespaces } from "#pantry/schema/seed/wildcard.ts";

/**
 * A named type, by its expanded name.
 */
export interface NamedTypeKey {
  readonly local: string;
  readonly namespace: string;
}

/**
 * An anonymous type, by the path of the declaration that holds it.
 */
export interface AnonymousTypeKey {
  readonly anonymous: string;
}

/**
 * A type: named, or anonymous.
 */
export type TypeKey = AnonymousTypeKey | NamedTypeKey;

/**
 * A global element and its declared type, in a schema set and version: a row of `declaredRoot`.
 */
export interface DeclaredRootRow {
  readonly local: string;
  readonly namespace: string;
  readonly set: SchemaSetHandle;
  readonly type: TypeKey;
  readonly version: SchemaVersionHandle;
}

/**
 * An element particle of a complex type's content model and its declared type, in a schema set and
 * version: a row of `declaredChild`.
 */
export interface DeclaredChildRow {
  readonly local: string;
  readonly namespace: string;
  readonly parent: TypeKey;
  readonly set: SchemaSetHandle;
  readonly type: TypeKey;
  readonly version: SchemaVersionHandle;
}

/**
 * A named type of a schema set and version: a row of `namedTypes`.
 */
export interface NamedTypeRow {
  readonly local: string;
  readonly namespace: string;
  readonly set: SchemaSetHandle;
  readonly version: SchemaVersionHandle;
}

/**
 * How a type derives from its base type: by extension or restriction, or, for a simple type, by
 * list or union.
 */
export type DerivationMethod = "extension" | "list" | "restriction" | "union";

/**
 * Whether a type definition is a simple type or a complex type.
 */
export type TypeVariety = "complex" | "simple";

/**
 * The constraining facets a simple type, or a complex type with simple content, states.
 */
export type FacetName =
  | "enumeration"
  | "fractionDigits"
  | "length"
  | "maxExclusive"
  | "maxInclusive"
  | "maxLength"
  | "minExclusive"
  | "minInclusive"
  | "minLength"
  | "pattern"
  | "totalDigits"
  | "whiteSpace";

const derivationMethods: readonly DerivationMethod[] = [
  "extension",
  "list",
  "restriction",
  "union",
];

const typeVarieties: readonly TypeVariety[] = ["complex", "simple"];

const facetNames: readonly FacetName[] = [
  "enumeration",
  "fractionDigits",
  "length",
  "maxExclusive",
  "maxInclusive",
  "maxLength",
  "minExclusive",
  "minInclusive",
  "minLength",
  "pattern",
  "totalDigits",
  "whiteSpace",
];

/**
 * A word of a row, which must be one of the allowed values; a word outside them is a composition
 * error.
 */
const choice = <A extends string>(allowed: readonly A[], word: string): A => {
  const found = allowed.find((candidate) => candidate === word);

  if (found === undefined) {
    throw new Error(`xsi writes the word "${word}", which is none of ${allowed.join(", ")}`);
  }

  return found;
};

/**
 * A named type's base type, derivation method and variety, in a schema set and version: a row of
 * `typeDerivation`.
 */
export interface TypeDerivationRow {
  readonly base: TypeKey;
  readonly method: DerivationMethod;
  readonly set: SchemaSetHandle;
  readonly type: TypeKey;
  readonly variety: TypeVariety;
  readonly version: SchemaVersionHandle;
}

/**
 * One attribute use of a named complex type, in a schema set and version: a row of `attributeUse`.
 */
export interface AttributeUseRow {
  readonly attributeType: TypeKey;
  readonly local: string;
  readonly namespace: string;
  readonly required: boolean;
  readonly set: SchemaSetHandle;
  readonly type: TypeKey;
  readonly version: SchemaVersionHandle;
}

/**
 * One constraining facet a type states, in a schema set and version: a row of `simpleFacet`.
 */
export interface SimpleFacetRow {
  readonly facet: FacetName;
  readonly set: SchemaSetHandle;
  readonly type: TypeKey;
  readonly value: string;
  readonly version: SchemaVersionHandle;
}

/**
 * The namespaces the tables name, by the code the rows write: the namespaces of `wildcard.ts`,
 * `xs` for XML Schema's own, and `none` for no namespace (an unqualified local element).
 */
export const typeNamespaces = {
  ...namespaces,
  none: "",
  xs: "http://www.w3.org/2001/XMLSchema",
} as const;

const namespaceByCode: ReadonlyMap<string, string> = new Map(Object.entries(typeNamespaces));

/**
 * The namespace a code stands for; a code outside `typeNamespaces` is a composition error.
 */
const namespaceOfCode = (code: string): string => {
  const namespace = namespaceByCode.get(code);

  if (namespace === undefined) {
    throw new Error(
      `xsi names the namespace code "${code}", which typeNamespaces does not declare`,
    );
  }

  return namespace;
};

/**
 * A name written `<code>:<local>`, as its namespace and local name.
 */
const nameOf = (text: string): NamedTypeKey => {
  const colon = text.indexOf(":");

  return { local: text.slice(colon + 1), namespace: namespaceOfCode(text.slice(0, colon)) };
};

/**
 * A type key as written: `<code>:<local>` for a named type, `!<path>` for an anonymous one.
 */
const typeOf = (text: string): TypeKey =>
  text.startsWith("!") ? { anonymous: text.slice(1) } : nameOf(text);

/**
 * One schema set and version's rows, as written.
 */
interface Block {
  readonly attributeUse: readonly string[];
  readonly declaredChild: readonly string[];
  readonly declaredRoot: readonly string[];
  readonly namedTypes: readonly string[];
  readonly set: SchemaSetHandle;
  readonly simpleFacet: readonly string[];
  readonly typeDerivation: readonly string[];
  readonly version: SchemaVersionHandle;
}

