/**
 * Every global element of a registry namespace, with its declared type.
 */
export const declaredRoot: readonly DeclaredRootRow[] = blocks.flatMap((block) =>
  block.declaredRoot.map((row) => {
    const [element = "", type = ""] = row.split(" ");

    return { ...nameOf(element), set: block.set, type: typeOf(type), version: block.version };
  }),
);

/**
 * Every element particle of a complex type's content model, with its parent and declared type.
 */
export const declaredChild: readonly DeclaredChildRow[] = blocks.flatMap((block) =>
  block.declaredChild.map((row) => {
    const [parent = "", element = "", type = ""] = row.split(" ");

    return {
      ...nameOf(element),
      parent: typeOf(parent),
      set: block.set,
      type: typeOf(type),
      version: block.version,
    };
  }),
);

/**
 * Every named type of each schema set and version, XML Schema's own included.
 */
export const namedTypes: readonly NamedTypeRow[] = blocks.flatMap((block) =>
  block.namedTypes.map((row) => ({ ...nameOf(row), set: block.set, version: block.version })),
);

/**
 * Every named type of each schema set and version but `xs:anyType`, with its base type.
 */
export const typeDerivation: readonly TypeDerivationRow[] = blocks.flatMap((block) =>
  block.typeDerivation.map((row) => {
    const [type = "", base = "", method = "", variety = ""] = row.split(" ");

    return {
      base: typeOf(base),
      method: choice(derivationMethods, method),
      set: block.set,
      type: typeOf(type),
      variety: choice(typeVarieties, variety),
      version: block.version,
    };
  }),
);

/**
 * Every attribute use of every named complex type, its base's uses included when it extends.
 */
export const attributeUse: readonly AttributeUseRow[] = blocks.flatMap((block) =>
  block.attributeUse.map((row) => {
    const [type = "", attribute = "", attributeType = "", use = ""] = row.split(" ");

    return {
      ...nameOf(attribute),
      attributeType: typeOf(attributeType),
      required: use === "required",
      set: block.set,
      type: typeOf(type),
      version: block.version,
    };
  }),
);

/**
 * Every constraining facet a named simple type, or a complex type with simple content derived by
 * restriction, states.
 */
export const simpleFacet: readonly SimpleFacetRow[] = blocks.flatMap((block) =>
  block.simpleFacet.map((row) => {
    const first = row.indexOf(" ");
    const second = row.indexOf(" ", first + 1);

    return {
      facet: choice(facetNames, row.slice(first + 1, second)),
      set: block.set,
      type: typeOf(row.slice(0, first)),
      value: row.slice(second + 1),
      version: block.version,
    };
  }),
);
